cases.script:
doc=$(help sleep)
case $doc in
  *"Suspend execution for specified period."*"GNU-style time intervals"*) printf 'sleep help contract ok\n' ;;
  *) exit 1 ;;
esac

start=$EPOCHREALTIME
sleep 0.02
end=$EPOCHREALTIME
start_s=${start%%.*}
start_f=${start#*.}
end_s=${end%%.*}
end_f=${end#*.}
start_us=$((10#$start_s * 1000000 + 10#$start_f))
end_us=$((10#$end_s * 1000000 + 10#$end_f))
elapsed_us=$((end_us - start_us))
(( elapsed_us >= 10000 )) || exit 1
printf 'minimum delay observed\n'
